# Manifest definitions
manifest_dir=root/'manifests/typography';manifest_dir.mkdir(parents=True,exist_ok=True)
preview_dir=root/'previews/typography';preview_dir.mkdir(parents=True,exist_ok=True)
for p in manifest_dir.glob('*.json'):p.unlink()
for p in preview_dir.glob('*.html'):p.unlink()

motions=['paper-slide','cut-paper-pop','ink-reveal']
registry=[]
for i,(slug,name,group,intents,guidance) in enumerate(systems,1):
    slots={
      'alignment':{'type':'enum','values':['left','center','right']},
      'emphasisWords':{'type':'array','maximum':guidance.get('emphasisWords',6)},
      'duration':{'type':'number','minimum':.6,'recommended':1.5,'maximum':5},
      'motionEnergy':{'type':'enum','values':['low','medium','high']},
    }
    for key,maxv in guidance.items():
        if key in ('items','emphasisWords'):continue
        if key=='itemCharacters':continue
        slots[key]={'type':'string','maxCharacters':maxv,'guidance':f'Maximum {maxv} characters; shorter copy is preferred.'}
    if 'items' in guidance:
        slots['items']={'type':'array','maximumItems':guidance['items'],'itemMaxCharacters':guidance['itemCharacters']}
    m={
      'id':f'typography.{slug}.paper-01','name':name,'version':'1.7.0','category':'typography','subtype':group,'slug':slug,'renderer':slug,'order':i,
      'intents':intents,'keywords':['typography','paper','animated','responsive',group,slug.replace('-',' '),*intents],
      'paperStyles':['clean-editorial','handmade-scrapbook','technical-notebook'],
      'aspectRatios':['16:9','1:1','9:16'],'slots':slots,
      'characterGuidance':guidance,'duration':{'minimum':.6,'recommended':1.5,'maximum':5},
      'motionEnergy':['low','medium','high'],'compatibleMotions':motions,'defaultMotion':motions[(i-1)%3],
      'soundTags':[f'typography.{slug}.soft','paper.text.reveal'],
      'themeTokens':['--paper-bg','--paper-surface','--paper-surface-alt','--ink','--ink-muted','--primary','--secondary','--accent','--highlight','--shadow-color','--shadow-opacity','--grain-opacity','--outline-width'],
      'accessibilityLabel':f'{name} animated paper typography component','responsiveText':True,'editable':True,'scalable':True,
      'agentSelection':{'useWhen':intents,'semanticRole':group,'copyGuidance':guidance}
    }
    registry.append(m);(manifest_dir/f'{i:02d}-{slug}.json').write_text(json.dumps(m,indent=2))

(root/'runtime/typography-registry.js').write_text('window.NEX_TYPOGRAPHY = '+json.dumps(registry,indent=2)+';\n')

