def comp_html(name,w,h,title,desc,slugs,palette,style):
    nodes=''.join(f'<div class="type-format-mount" data-type="{slug}"></div>' for slug in slugs)
    return f'''<!doctype html><html lang="en" data-paper-style="{style}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><link rel="stylesheet" href="../styles/tokens.css"><link rel="stylesheet" href="../styles/paper.css"><link rel="stylesheet" href="../styles/motion.css"><link rel="stylesheet" href="../styles/typography.css"><link rel="stylesheet" href="../styles/typography-scenes.css"></head><body><main id="{name}" class="type-format-scene" data-composition-id="{name}" data-start="0" data-duration="8" data-track-index="1" data-width="{w}" data-height="{h}"><div class="type-format-layout"><section class="type-format-copy"><div><div class="type-format-tag">NEXSTUDIO / BATCH 8</div><h1>{title}</h1><p>{desc}</p></div><div class="type-format-tag">RESPONSIVE · EDITABLE · SEEKABLE</div></section><section class="type-format-board">{nodes}</section></div></main><script src="../vendor/gsap-compat.js"></script><script src="../runtime/theme.js"></script><script src="../runtime/motion-registry.js"></script><script src="../runtime/motion-engine.js"></script><script src="../runtime/typography-registry.js"></script><script src="../runtime/typography-samples.js"></script><script src="../components/typography.js"></script><script>NexTheme.applyPalette('{palette}');NexTheme.setStyle('{style}');const master=NexMotion.createTimeline();document.querySelectorAll('[data-type]').forEach((m,i)=>{{const slug=m.dataset.type,s=window.NEX_TYPOGRAPHY_SAMPLES[slug]||{{}};const c=NexTypography.create(slug,{{...s,style:'{style}',alignment:i%2?'left':'center'}});m.appendChild(c);NexTypography.fitText(c);const child=NexTypography.animate(c,{{duration:1.45,energy:i%3===0?'high':'medium'}});master.addUpdate(.35+i*.55,Math.min(2,child.duration()),p=>child.seek(p*child.duration()),'none')}});master.addUpdate(0,8,p=>{{document.querySelector('.type-format-layout').style.setProperty('--scene-progress',p)}},'none');master.seek(0);window.__timelines=window.__timelines||{{}};window.__timelines['{name}']=master;</script></body></html>'''

