# Kinetic 20s composition and runtime
slugs=['chapter-opener','question-hook','statistic-headline','word-by-word-emphasis','quote-card','call-to-action-card']
scenes=''.join(f'<section class="kinetic-scene" data-scene="{i}" data-type="{s}"><div class="scene-mount"></div></section>' for i,s in enumerate(slugs))
kinetic=f'''<!doctype html><html lang="en" data-paper-style="bold-paper-collage"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kinetic Typography Demonstration</title><link rel="stylesheet" href="../styles/tokens.css"><link rel="stylesheet" href="../styles/paper.css"><link rel="stylesheet" href="../styles/motion.css"><link rel="stylesheet" href="../styles/typography.css"><link rel="stylesheet" href="../styles/typography-scenes.css"></head><body><main id="kinetic-typography-demo" class="kinetic-demo" data-composition-id="kinetic-typography-demo" data-start="0" data-duration="20" data-track-index="1" data-width="1920" data-height="1080">{scenes}<div class="kinetic-transition"></div><div class="kinetic-corner">NEXSTUDIO / TYPOGRAPHY SYSTEM / 20.0 SEC</div><div class="kinetic-progress"><span></span></div></main><script src="../vendor/gsap-compat.js"></script><script src="../runtime/theme.js"></script><script src="../runtime/motion-registry.js"></script><script src="../runtime/motion-engine.js"></script><script src="../runtime/typography-registry.js"></script><script src="../runtime/typography-samples.js"></script><script src="../components/typography.js"></script><script src="../runtime/kinetic-typography-demo.js"></script></body></html>'''
(root/'compositions/kinetic-typography-demo.html').write_text(kinetic)
(root/'runtime/kinetic-typography-demo.js').write_text(r'''
(()=>{NexTheme.applyPalette('warm');const sceneEls=[...document.querySelectorAll('.kinetic-scene')],starts=[0,3.25,6.5,9.75,13,16.35],master=NexMotion.createTimeline(),transition=document.querySelector('.kinetic-transition'),progress=document.querySelector('.kinetic-progress span');sceneEls.forEach((scene,i)=>{const slug=scene.dataset.type,s={...(window.NEX_TYPOGRAPHY_SAMPLES[slug]||{})};if(slug==='statistic-headline')s.value='308';const c=NexTypography.create(slug,{...s,style:i%3===0?'clean-editorial':i%3===1?'handmade-scrapbook':'technical-notebook',alignment:i%2?'center':'left',energy:i%2?'high':'medium'});scene.querySelector('.scene-mount').appendChild(c);NexTypography.fitText(c);const child=NexTypography.animate(c,{duration:1.65,energy:i%2?'high':'medium'});master.fromTo(scene,{opacity:0,scale:1.025},{opacity:1,scale:1,duration:.42,ease:'power2.out'},starts[i]);master.addUpdate(starts[i]+.08,Math.min(2.2,child.duration()),p=>child.seek(p*child.duration()),'none');if(i>0){master.fromTo(transition,{x:-2100,rotation:-2},{x:2100,rotation:2,duration:.72,ease:'power3.inOut'},starts[i]-.28)}});master.addUpdate(0,20,p=>{progress.style.width=`${p*100}%`},'none');master.addUpdate(18.2,1.8,p=>{const c=sceneEls[5].querySelector('.nex-type');c.style.transform=`translateY(${Math.sin(p*Math.PI*3)*3}px)`;c.style.filter=`drop-shadow(0 ${12+8*p}px ${18+8*p}px rgba(0,0,0,.18))`},'sine.inOut');master.seek(0);window.__timelines=window.__timelines||{};window.__timelines['kinetic-typography-demo']=master;})();
''')

# docs
(root/'TYPOGRAPHY_API.md').write_text('''# NexStudio Animated Typography API\n\n```js\nconst card = NexTypography.create("statistic-headline", {\n  value: "308", title: "Reusable components", body: "Configured from data.",\n  style: "clean-editorial", alignment: "left", emphasis: "Reusable"\n});\ncontainer.appendChild(card);\nNexTypography.fitText(card);\nNexTypography.animate(card, { duration: 1.8, energy: "high" }).restart();\n```\n\n## Public methods\n\n- `NexTypography.create(idOrSlug, config)`\n- `NexTypography.fitText(element)`\n- `NexTypography.animate(element, options)`\n- `NexTypography.update(element, config)`\n- `NexTypography.setStyle(element, style)`\n- `NexTypography.setAlignment(element, alignment)`\n\nEach manifest defines explicit copy limits in `characterGuidance` and `slots`. No ordinary wrapping depends on fixed `<br>` tags.\n''')

